import{_ as a}from"./chunks/android-01-accueil-image-et-bannieres.BHxZEgjx.js";import{_ as t,o as r,c as s,a5 as i}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-11-08-bornes-images-accueil-bannieres/01-accueil-image-et-bannieres.webp",n="/VendoraSystem-docs/captures/2026-11-08-bornes-images-accueil-bannieres/02-banniere-touchee-categorie-desserts.webp",c="/VendoraSystem-docs/captures/2026-11-08-bornes-images-accueil-bannieres/03-iphone-accueil-compact.webp",d="/VendoraSystem-docs/captures/2026-11-08-bornes-images-accueil-bannieres/android-02-demande-epinglage.webp",l="/VendoraSystem-docs/captures/2026-11-08-bornes-images-accueil-bannieres/android-03-ecran-non-epingle.webp",P=JSON.parse(`{"title":"Bornes : image d'accueil et bannières affichées (08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-bornes-images-accueil-bannieres.md","filePath":"generated/preuves/2026-11-08-bornes-images-accueil-bannieres.md","lastUpdated":null}`),u={name:"preuves/2026-11-08-bornes-images-accueil-bannieres.md"};function p(m,e,g,b,h,f){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="bornes-image-d-accueil-et-bannieres-affichees-08-11-2026" tabindex="-1">Bornes : image d&#39;accueil et bannières affichées (08/11/2026) <a class="header-anchor" href="#bornes-image-d-accueil-et-bannieres-affichees-08-11-2026" aria-label="Permalink to &quot;Bornes : image d&#39;accueil et bannières affichées (08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-bornes-images-accueil-bannieres</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Bornes : images d&#39;accueil et bannières non affichées ». Vraie stack : serveur du worktree (port 8093, base dédiée), commerce FICTIF « Le Petit Bistrot (démo) » (<code>seed-demo.py</code>), preset « Borne entrée » avec une image d&#39;accueil et deux bannières générées (fictives) + une bannière sans image, iPad Air 11&quot; et iPhone 17 Pro simulés (simulateurs dédiés), app pilotée par le pilote XCUITest du centre d&#39;aide.</p><p><strong>Cause</strong> : le cache local des assets ne gardait que le logo (un seul asset, les autres purgés) ; l&#39;image d&#39;accueil et les images des bannières du preset n&#39;étaient jamais téléchargées ni affichées. Correctif : cache multi-assets (<code>KioskAssetSync</code>, kind <code>KIOSK_IMAGE</code>) téléchargé après chaque pull, lu hors ligne ; accueil des deux apps.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="'+o+'" alt="Accueil iPad"></td><td><strong>Après</strong> — iPad, paysage : image d&#39;accueil (1), langue (2), rappel de verrouillage (3), bannières actives (4) — avec image si elle est en cache, titre seul sinon (« Café offert… »). Avant : texte seul, ni image ni bannière.</td></tr><tr><td><img src="'+n+'" alt="Bannière touchée"></td><td>Bannière « Desserts maison » touchée : après « Sur place », le catalogue s&#39;ouvre sur sa catégorie cible (1).</td></tr><tr><td><img src="'+c+'" alt="iPhone compact"></td><td>iPhone (hors cible tablette) : mise en page compacte — image (1) à la largeur de l&#39;écran, bannières défilantes (2), langue et rappel empilés (3).</td></tr></tbody></table><p>Mode verrouillé Android hors device owner : <code>startLockTask()</code> demande l&#39;épinglage à l&#39;utilisateur ; l&#39;état réel (<code>lockTaskModeState</code> : appareil dédié / épinglé / non épinglé) est lu chaque seconde, affiché sur l&#39;accueil (« Écran non épinglé : acceptez « Épingler l&#39;application »… ») et remonté au heartbeat (spec 09 RG-KIOSK-01).</p><h2 id="captures-android-tablette-08-11-2026-au-soir" tabindex="-1">Captures Android (tablette, 08/11/2026 au soir) <a class="header-anchor" href="#captures-android-tablette-08-11-2026-au-soir" aria-label="Permalink to &quot;Captures Android (tablette, 08/11/2026 au soir)&quot;">​</a></h2><p>Captures Android faites le 08/11/2026 au soir sur les émulateurs du projet (dérogation accordée pour ce lot) : tablette <code>emulator-5554</code> (AVD « Kds_Tablet », 1600 × 1000) et téléphone <code>emulator-5556</code> (AVD « Medium_Phone_API_36.1 », 1080 × 2400), app de debug <code>pos.android</code> construite depuis <code>main</code> (0d1aecf5), commerce de démo FICTIF « Le Petit Bistrot (démo) » (<code>bistrot.demo+and1108@vendora.test</code>, <code>seed-demo.py --no-activity</code>) sur le serveur de dev <code>localhost:8080</code>. Gestes par <code>help/tools/mobile/drv.py</code> (adb), annotations par <code>annotate.py</code>. Preset « Borne entrée » du commerce de démo : image d&#39;accueil et deux images de bannière <strong>générées</strong> (dégradés, texte fictif) téléversées par <code>POST /stores/{id}/kiosk-assets</code>, plus une bannière sans image (« Café offert avec la formule midi ») ; tablette appairée en <strong>borne</strong> avec ce preset. Scénario : <code>help/tools/mobile/scenarios/borne-preparer-la-borne-android.json</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+a+'" alt=""></td><td>Accueil : image d&#39;accueil (1), bannières (2) — avec image, ou titre seul pour celle qui n&#39;en a pas.</td></tr><tr><td><img src="'+d+'" alt=""></td><td>Au lancement, <code>startLockTask()</code> : fenêtre système d&#39;épinglage (1, en anglais : langue de l&#39;émulateur), « Got it » (2) pour accepter.</td></tr><tr><td><img src="'+l+'" alt=""></td><td>Épinglage refusé (« No thanks ») : en bas de l&#39;accueil, langues (1) et « Écran non épinglé : acceptez « Épingler l&#39;application » (ou provisionnez l&#39;appareil en appareil dédié) pour verrouiller la borne » (2).</td></tr></tbody></table><p><strong>Défaut vu</strong> : sur la tablette 1600 × 1000 en paysage, le choix de la langue et le rappel d&#39;épinglage sont <strong>sous la ligne de flottaison</strong> — il faut faire défiler l&#39;accueil pour les voir (capture 03 prise après défilement ; la capture 01 ne les montre pas). Sur iPad, tout tient à l&#39;écran. Rien n&#39;indique au client que l&#39;accueil défile.</p></div>',3)])])}const A=t(u,[["render",p]]);export{P as __pageData,A as default};
